'use client';

import { useEffect, useId, useRef, useState } from 'react';
import { focusMenuItem, handleMenuKeys } from './menu-keys';
import { useDismiss } from './use-dismiss';
import './split-action-button.css';

export interface SplitAction {
  id: string;
  label: string;
}

export interface SplitActionButtonProps {
  label: string;
  onAction: () => void;
  /** Other actions, shown in the menu behind the caret. */
  options: SplitAction[];
  onSelect: (id: string) => void;
  /** Accessible name for the caret, for example "More save options". */
  menuLabel: string;
  className?: string;
}

/**
 * A primary action with a separate caret for related actions. The menu
 * supports arrow keys, Home, End and Escape, closes on an outside press, and
 * returns focus to the caret after a choice or Escape.
 */
export function SplitActionButton({
  label,
  onAction,
  options,
  onSelect,
  menuLabel,
  className = '',
}: SplitActionButtonProps) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const caret = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const id = useId();
  const firstOrLast = useRef<'first' | 'last'>('first');

  useEffect(() => {
    if (open) focusMenuItem(menu.current, firstOrLast.current);
  }, [open]);

  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) caret.current?.focus();
  };
  useDismiss(open, [root], (reason) => close(reason === 'escape'));

  return (
    <div ref={root} className={`mg-split ${className}`} data-open={open}>
      <button type='button' className='mg-split__main' onClick={onAction}>
        {label}
      </button>
      <button
        ref={caret}
        type='button'
        className='mg-split__caret'
        aria-label={menuLabel}
        aria-haspopup='menu'
        aria-expanded={open}
        aria-controls={id}
        onClick={() => {
          firstOrLast.current = 'first';
          setOpen((value) => !value);
        }}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            firstOrLast.current = event.key === 'ArrowUp' ? 'last' : 'first';
            setOpen(true);
          }
        }}
      >
        <span aria-hidden='true' className='mg-split__chevron' />
      </button>
      <div
        ref={menu}
        id={id}
        role='menu'
        aria-label={menuLabel}
        className='mg-split__menu'
        hidden={!open}
        onKeyDown={(event) => {
          if (event.key === 'Tab') close(false);
          else handleMenuKeys(event, menu.current);
        }}
      >
        {options.map((option) => (
          <button
            key={option.id}
            type='button'
            role='menuitem'
            tabIndex={-1}
            className='mg-split__item'
            onClick={() => {
              onSelect(option.id);
              close(true);
            }}
          >
            {option.label}
          </button>
        ))}
      </div>
    </div>
  );
}

.mg-split {
  position: relative;
  display: inline-flex;
  color: #fff;
}

.mg-split__main,
.mg-split__caret {
  min-height: 44px;
  border: 0;
  background: var(--mg-accent, #164cff);
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-split__main {
  padding: 0 18px;
  border-radius: 10px 0 0 10px;
}

.mg-split__caret {
  display: grid;
  place-items: center;
  width: 44px;
  border-left: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 0 10px 10px 0;
}

.mg-split__main:hover,
.mg-split__caret:hover {
  background: #0f3ad6;
}

.mg-split__main:focus-visible,
.mg-split__caret:focus-visible {
  outline: 3px solid var(--mg-ink, #0c1738);
  outline-offset: 2px;
  z-index: 1;
}

.mg-split__chevron {
  width: 8px;
  height: 8px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
  transition: transform 220ms ease;
}

.mg-split[data-open='true'] .mg-split__chevron {
  transform: translateY(2px) rotate(225deg);
}

.mg-split__menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 10;
  display: grid;
  min-width: 200px;
  padding: 6px;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 16px 32px -16px rgba(12, 23, 56, 0.45);
  transform-origin: top right;
  animation: mg-split-in 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-split__menu[hidden] {
  display: none;
}

.mg-split__item {
  min-height: 40px;
  padding: 0 12px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--mg-ink, #0c1738);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.mg-split__item:hover,
.mg-split__item:focus {
  outline: none;
  background: var(--mg-foam, #e6ecff);
}

.mg-split__item:focus-visible {
  box-shadow: inset 0 0 0 2px var(--mg-accent, #164cff);
}

@keyframes mg-split-in {
  from {
    opacity: 0;
    transform: scale(0.94) translateY(-4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-split__menu {
    animation: none;
  }
  .mg-split__chevron {
    transition: none;
  }
}

const ITEM =
  '[role="menuitem"]:not([aria-disabled="true"]), [role="menuitemradio"], [role="menuitemcheckbox"]';

function items(menu: HTMLElement) {
  return Array.from(menu.querySelectorAll<HTMLElement>(ITEM)).filter(
    (item) => item.closest('[role="menu"]') === menu
  );
}

/** Moves focus to the first (or last) item of `menu`. */
export function focusMenuItem(
  menu: HTMLElement | null,
  which: 'first' | 'last' = 'first'
) {
  if (!menu) return;
  const list = items(menu);
  list[which === 'first' ? 0 : list.length - 1]?.focus();
}

/**
 * Arrow, Home and End navigation between the items of `menu`. Call it from
 * the menu's keydown handler. Returns true when the key was handled.
 */
export function handleMenuKeys(
  event: { key: string; preventDefault(): void },
  menu: HTMLElement | null
): boolean {
  if (!menu) return false;
  const list = items(menu);
  if (list.length === 0) return false;
  const index = list.indexOf(document.activeElement as HTMLElement);
  let next: number;
  switch (event.key) {
    case 'ArrowDown':
      next = (index + 1) % list.length;
      break;
    case 'ArrowUp':
      next = index <= 0 ? list.length - 1 : index - 1;
      break;
    case 'Home':
      next = 0;
      break;
    case 'End':
      next = list.length - 1;
      break;
    default:
      return false;
  }
  event.preventDefault();
  list[next].focus();
  return true;
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

export type DismissReason = 'escape' | 'outside';

/**
 * While `active`, calls `onDismiss` when Escape is pressed or when a pointer
 * goes down outside every element in `refs`. Decide where focus goes in
 * `onDismiss`: back to the trigger after Escape, left alone after an
 * outside press.
 */
export function useDismiss(
  active: boolean,
  refs: RefObject<HTMLElement | null>[],
  onDismiss: (reason: DismissReason) => void
) {
  const callback = useRef(onDismiss);
  callback.current = onDismiss;
  const inside = useRef(refs);
  inside.current = refs;

  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      callback.current('escape');
    };
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (inside.current.some((ref) => ref.current?.contains(target))) return;
      callback.current('outside');
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('pointerdown', onPointerDown);
    };
  }, [active]);
}
